<?php
declare(strict_types=1);
require __DIR__ . '/includes/bootstrap.php';
$user=app_require_permission('recipes.view');
$canEdit=app_has_permission('recipes.edit',$user);$canMap=app_has_permission('recipes.ai_map',$user);$canAgent=app_has_permission('recipes.agent',$user);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Recipe Library & AI Mapper</title>
<style>
:root{--bg:#f3f2ee;--panel:#fff;--ink:#171815;--muted:#70736d;--line:#dddcd6;--accent:#d94a2b;--dark:#171b1a;--soft:#fff1ec;--shadow:0 14px 42px rgba(25,26,22,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}button,input,select,textarea{font:inherit}.topbar{height:64px;position:sticky;top:0;z-index:30;display:flex;align-items:center;justify-content:space-between;padding:0 20px;border-bottom:1px solid var(--line);background:#fff}.brand{display:flex;gap:11px;align-items:center}.logo{width:38px;height:38px;display:grid;place-items:center;border-radius:11px;background:var(--dark);color:#fff;font-weight:900}.brand small{display:block;color:var(--muted)}.actions{display:flex;gap:8px}.btn{min-height:38px;display:inline-flex;align-items:center;justify-content:center;gap:6px;border:1px solid var(--line);border-radius:10px;background:#fff;color:var(--ink);padding:8px 12px;font-weight:800;text-decoration:none}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.btn.danger{color:#9d2b23}.app{display:grid;grid-template-columns:320px minmax(0,1fr);min-height:calc(100vh - 64px)}.sidebar{border-right:1px solid var(--line);background:#faf9f6;padding:16px;position:sticky;top:64px;height:calc(100vh - 64px);overflow:auto}.sidebar-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.sidebar h2{margin:0;font-size:18px}.field{width:100%;min-height:40px;padding:9px 11px;border:1px solid var(--line);border-radius:10px;background:#fff;outline:none}.field:focus{border-color:rgba(217,74,43,.55);box-shadow:0 0 0 4px rgba(217,74,43,.08)}.recipe-list{display:grid;gap:7px;margin-top:10px}.recipe-agent{margin-top:14px;padding:13px;border:1px solid #ead2c9;border-radius:14px;background:linear-gradient(145deg,#fff,#fff7f4)}.recipe-agent h3{margin:0 0 6px;font-size:13px}.recipe-agent p{margin:0;color:var(--muted);font-size:10px;line-height:1.45}.recipe-agent .quick{display:flex;flex-wrap:wrap;gap:6px;margin-top:9px}.recipe-agent .quick button{border:1px solid #ead2c9;border-radius:999px;background:#fff;padding:6px 8px;font-size:9px;font-weight:800;cursor:pointer}.recipe-card{width:100%;padding:12px;border:1px solid var(--line);border-radius:12px;background:#fff;text-align:left}.recipe-card.active{border-color:#e69d89;background:#fff6f2}.recipe-card strong{display:block;font-size:12px}.recipe-card span{display:block;margin-top:4px;color:var(--muted);font-size:9px}.map-dot{display:inline-block!important;width:7px;height:7px;border-radius:50%;background:#b8b8b3;margin-right:5px}.map-dot.mapped{background:#1b8b54}.editor{padding:26px clamp(18px,3vw,42px) 70px}.empty-editor{max-width:760px;margin:80px auto;padding:45px;border:1px dashed #c7c6c0;border-radius:24px;text-align:center;color:var(--muted);background:#fff}.hero{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:18px}.eyebrow{margin:0;color:var(--accent);font-size:9px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.hero h1{margin:6px 0 6px;font-size:40px;letter-spacing:-.05em}.hero p{margin:0;color:var(--muted)}.grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(300px,.7fr);gap:16px}.card{padding:19px;border:1px solid var(--line);border-radius:18px;background:#fff;box-shadow:0 7px 24px rgba(25,26,22,.035)}.card h3{margin:0 0 13px;font-size:15px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.form-group{display:grid;gap:5px}.form-group.wide{grid-column:1/-1}.form-group label{font-size:9px;font-weight:900;text-transform:uppercase;color:#666b65}.form-group textarea{min-height:100px;resize:vertical}.ingredients{display:grid;gap:8px}.ingredient-row{display:grid;grid-template-columns:82px 90px minmax(150px,1fr) minmax(120px,.7fr) 34px;gap:6px}.instruction-row{display:grid;grid-template-columns:28px minmax(0,1fr) 34px;gap:7px;align-items:start}.instruction-row span{width:28px;height:28px;display:grid;place-items:center;border-radius:8px;background:#f1f0ec;font-size:10px;font-weight:900}.remove{border:1px solid var(--line);border-radius:8px;background:#fff;color:#a62a24}.sub-actions{display:flex;gap:7px;margin-top:9px}.image-drop{position:relative;display:grid;place-items:center;min-height:250px;border:2px dashed #cfcec7;border-radius:16px;background:#f9f8f5;overflow:hidden;text-align:center}.image-drop img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#efeee9}.image-drop .copy{position:relative;z-index:2;max-width:260px;padding:20px}.image-drop img+.copy{display:none}.image-drop strong{display:block}.image-drop p{margin:6px 0 0;color:var(--muted);font-size:10px;line-height:1.5}.image-input{display:none}.mapping{margin-top:12px;padding:13px;border:1px solid #ead2c9;border-radius:13px;background:#fff8f5}.mapping h4{margin:0 0 6px;font-size:12px}.mapping p{margin:5px 0;color:var(--muted);font-size:10px;line-height:1.5}.mapping a{color:#a53922;font-weight:800;word-break:break-all}.confidence{height:7px;border-radius:999px;background:#ebe9e4;overflow:hidden;margin-top:8px}.confidence i{display:block;height:100%;background:var(--accent)}.analysis-box{margin-top:10px;padding:12px;border-radius:12px;background:#f5f4f0}.analysis-box small{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;font-weight:900}.analysis-box strong{display:block;margin-top:4px;font-size:13px}.analysis-box p{margin:5px 0 0;color:var(--muted);font-size:10px;line-height:1.45}.source{padding:11px;border-radius:11px;background:#f6f5f2;font-size:10px}.source strong{display:block}.source a{display:block;margin-top:4px;color:#a53922;word-break:break-all}.status{padding:5px 8px;border-radius:999px;background:#f1f0ec;color:#656963;font-size:9px;font-weight:900;text-transform:uppercase}.status.mapped{background:#e9f7ee;color:#17683d}.toast{position:fixed;right:20px;bottom:20px;z-index:70;padding:11px 14px;border-radius:11px;background:#171b1a;color:#fff;box-shadow:var(--shadow);font-size:11px}.hidden{display:none}.spinner{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:1000px){.app{grid-template-columns:260px minmax(0,1fr)}.grid{grid-template-columns:1fr}.ingredient-row{grid-template-columns:70px 75px 1fr 34px}.ingredient-row .notes{grid-column:1/4}}@media(max-width:720px){.app{grid-template-columns:1fr}.sidebar{position:relative;top:0;height:auto;border-right:0;border-bottom:1px solid var(--line)}.recipe-list{grid-template-columns:repeat(2,1fr)}.hero{flex-direction:column}.form-grid{grid-template-columns:1fr}.form-group.wide{grid-column:auto}.ingredient-row{grid-template-columns:1fr 1fr 34px}.ingredient-row .ingredient,.ingredient-row .notes{grid-column:1/3}}
</style></head><body>
<header class="topbar"><div class="brand"><div class="logo">G</div><div><strong>Recipe Library</strong><small>AI-assisted restaurant knowledge</small></div></div><div class="actions"><a class="btn" href="wholesale-pipeline.php">Wholesale</a><a class="btn" href="index.php">Workspace</a><?php if($canEdit): ?><button class="btn primary" id="newRecipe">New Recipe</button><?php endif ?></div></header>
<div class="app"><aside class="sidebar"><div class="sidebar-head"><h2>Recipes</h2><span class="status" id="recipeCount">0</span></div><input class="field" id="search" placeholder="Search recipes, ingredients, source..."><div class="recipe-list" id="recipeList"></div><section class="recipe-agent"><h3>Recipe + Production Standards Agent</h3><p>Uses the shared Gelato Agent. The selected recipe ID is sent as context and the canonical recipe is re-resolved on the server.</p><?php if($canAgent): ?><div class="quick"><button data-recipe-agent-prompt="Show recipe production standards that need attention">Standards gaps</button><button data-recipe-agent-prompt="How do we make this recipe?">This recipe</button><button data-recipe-agent-prompt="Scale this recipe to 40 portions">Scale to 40</button><button data-recipe-agent-prompt="Check this recipe for common allergen keywords">Allergen screen</button></div><?php else: ?><p style="margin-top:8px">Your role does not include Recipe Agent access.</p><?php endif; ?></section></aside><main class="editor"><div class="empty-editor" id="emptyEditor"><h2>Select a recipe</h2><p>Open an existing recipe or create one. Each recipe can store its own source image, AI extraction, and online recipe mapping.</p></div><section class="hidden" id="editor"></section></main></div><div class="toast hidden" id="toast"></div>
<script>window.RECIPE_CONFIG={csrf:<?= json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,canEdit:<?= $canEdit?'true':'false' ?>,canMap:<?= $canMap?'true':'false' ?>};</script>
<script>
(()=>{const cfg=window.RECIPE_CONFIG;let recipes=[],activeId='',detail=null;const esc=v=>String(v??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));const toast=t=>{const e=document.getElementById('toast');e.textContent=t;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),1800)};async function api(url,options={}){const isBody=!!options.body;const r=await fetch(url,{cache:'no-store',headers:{Accept:'application/json',...(isBody?{'Content-Type':'application/json','X-CSRF-Token':cfg.csrf}:{}),...(options.headers||{})},...options});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed.');return d}
async function loadList(){const q=document.getElementById('search').value.trim();const d=await api('api/recipes.php?action=list&q='+encodeURIComponent(q));recipes=d.recipes||[];document.getElementById('recipeCount').textContent=recipes.length;document.getElementById('recipeList').innerHTML=recipes.length?recipes.map(r=>`<button class="recipe-card ${r.id===activeId?'active':''}" data-id="${esc(r.id)}"><strong>${esc(r.name)}</strong><span><i class="map-dot ${r.mappingStatus==='mapped'?'mapped':''}"></i>${esc(r.category||'Uncategorized')} · ${r.imageCount||0} image${Number(r.imageCount)===1?'':'s'}</span></button>`).join(''):'<div style="color:var(--muted);font-size:11px;padding:20px 5px">No recipes yet.</div>';document.querySelectorAll('.recipe-card').forEach(b=>b.onclick=()=>openRecipe(b.dataset.id))}
async function openRecipe(id){activeId=id;const d=await api('api/recipes.php?action=detail&id='+encodeURIComponent(id));detail=d;renderEditor();await loadList();window.GelatoRecipeAgentContext?.publish?.();document.dispatchEvent(new CustomEvent('gelato-recipe-selected',{detail:{id:activeId}}))}
function ingredientRow(item={}){return `<div class="ingredient-row"><input class="field qty" placeholder="Qty" value="${esc(item.quantity||'')}"><input class="field unit" placeholder="Unit" value="${esc(item.unit||'')}"><input class="field ingredient" placeholder="Ingredient" value="${esc(item.ingredient||item.name||'')}"><input class="field notes" placeholder="Prep / notes" value="${esc(item.notes||'')}"><button class="remove" type="button">×</button></div>`}
function instructionRow(text='',i=0){return `<div class="instruction-row"><span>${i+1}</span><textarea class="field instruction" rows="2">${esc(typeof text==='string'?text:text?.text||'')}</textarea><button class="remove" type="button">×</button></div>`}
function renderEditor(){const r=detail.recipe,images=detail.images||[],primary=images[0],analysis=primary?.analysis,match=analysis?.onlineMatch||null;document.getElementById('emptyEditor').classList.add('hidden');const ed=document.getElementById('editor');ed.classList.remove('hidden');ed.innerHTML=`<div class="hero"><div><p class="eyebrow">Restaurant recipe</p><h1>${esc(r.name)}</h1><p>${esc(r.category||'Recipe library')} · Updated ${esc(r.updatedAt||'')}</p></div><span class="status ${r.mappingStatus==='mapped'?'mapped':''}">${esc(r.mappingStatus)}</span></div><div class="grid"><div><section class="card"><h3>Recipe details</h3><div class="form-grid"><div class="form-group"><label>Name</label><input class="field" id="rName" value="${esc(r.name)}" ${cfg.canEdit?'':'disabled'}></div><div class="form-group"><label>Category</label><input class="field" id="rCategory" value="${esc(r.category)}" ${cfg.canEdit?'':'disabled'} placeholder="Gelato, dough, sauce, prep..."></div><div class="form-group wide"><label>Description</label><textarea class="field" id="rDescription" ${cfg.canEdit?'':'disabled'}>${esc(r.description)}</textarea></div><div class="form-group"><label>Yield quantity</label><input class="field" id="rYieldQty" type="number" step=".01" value="${r.yieldQuantity??''}" ${cfg.canEdit?'':'disabled'}></div><div class="form-group"><label>Yield unit</label><input class="field" id="rYieldUnit" value="${esc(r.yieldUnit)}" ${cfg.canEdit?'':'disabled'} placeholder="pans, quarts, kg, portions..."></div></div></section><section class="card" style="margin-top:14px"><h3>Ingredients</h3><div class="ingredients" id="ingredientRows">${(r.ingredients||[]).map(ingredientRow).join('')||ingredientRow()}</div>${cfg.canEdit?'<div class="sub-actions"><button class="btn" id="addIngredient">+ Ingredient</button></div>':''}</section><section class="card" style="margin-top:14px"><h3>Method / instructions</h3><div class="ingredients" id="instructionRows">${(r.instructions||[]).map(instructionRow).join('')||instructionRow('',0)}</div>${cfg.canEdit?'<div class="sub-actions"><button class="btn" id="addInstruction">+ Step</button></div>':''}</section><section class="card" style="margin-top:14px"><h3>Internal notes</h3><textarea class="field" id="rNotes" rows="5" ${cfg.canEdit?'':'disabled'}>${esc(r.notes)}</textarea>${cfg.canEdit?'<div class="sub-actions"><button class="btn primary" id="saveRecipe">Save recipe</button><button class="btn danger" id="archiveRecipe">Archive</button></div>':''}</section></div><aside><section class="card"><h3>Recipe image + AI mapping</h3><label class="image-drop" id="imageDrop">${primary?`<img src="${esc(primary.imageUrl)}" alt="Uploaded recipe image">`:''}<div class="copy"><strong>${primary?'Replace recipe image':'Upload a recipe image'}</strong><p>Photograph a handwritten card, printed recipe, prep sheet, cookbook page, or finished dish. AI extracts the recipe and searches for the closest online source.</p></div><input class="image-input" id="imageInput" type="file" accept="image/jpeg,image/png,image/webp" ${cfg.canEdit?'':'disabled'}></label>${cfg.canEdit?`<div class="sub-actions"><button class="btn ${cfg.canMap?'primary':''}" id="uploadImage">${cfg.canMap?'Upload + AI Map Online':'Upload Image'}</button></div>`:''}${primary?`<div class="analysis-box"><small>Latest image</small><strong>${esc(primary.fileName)}</strong><p>${Math.round((primary.fileSize||0)/1024)} KB · ${esc(primary.mappingStatus)}</p></div>`:''}${match?mappingHtml(match,analysis,primary):sourceHtml(r)}</section><section class="card" style="margin-top:14px"><h3>Mapped source</h3>${sourceHtml(r)}<div class="form-group" style="margin-top:10px"><label>Mapping notes</label><textarea class="field" id="rMapNotes" rows="4" ${cfg.canEdit?'':'disabled'}>${esc(r.mappingNotes)}</textarea></div></section></aside></div>`;bindEditor()}
function sourceHtml(r){return r.sourceUrl?`<div class="source"><strong>${esc(r.sourceTitle||r.sourceDomain||'Online recipe')}</strong><a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(r.sourceUrl)}</a><div class="confidence"><i style="width:${Math.round(Number(r.sourceConfidence||0)*100)}%"></i></div><small>${Math.round(Number(r.sourceConfidence||0)*100)}% mapping confidence</small></div>`:'<div class="source"><strong>No online recipe mapped yet</strong><span>Upload a recipe image and run AI mapping.</span></div>'}
function mappingHtml(match,analysis,primary){const url=match.url||'';return `<div class="mapping"><h4>AI mapping result</h4><p><strong>${esc(analysis.recipeName||'Recognized recipe')}</strong></p>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(match.title||url)}</a><div class="confidence"><i style="width:${Math.round(Number(match.confidence||0)*100)}%"></i></div><p>${Math.round(Number(match.confidence||0)*100)}% confidence · ${esc(match.why||analysis.mappingNotes||'')}</p>`:`<p>${esc(analysis.mappingNotes||'The image was extracted, but no credible online match was found yet.')}</p>`}${cfg.canMap?`<button class="btn primary" id="applyAI" data-image="${primary.id}" style="margin-top:7px">Apply AI extraction to recipe</button>`:''}</div>`}
function renumber(){document.querySelectorAll('#instructionRows .instruction-row span').forEach((s,i)=>s.textContent=i+1)}
function bindEditor(){document.querySelectorAll('.remove').forEach(b=>b.onclick=()=>{b.parentElement.remove();renumber()});if(!cfg.canEdit)return;document.getElementById('addIngredient').onclick=()=>{document.getElementById('ingredientRows').insertAdjacentHTML('beforeend',ingredientRow());bindEditor()};document.getElementById('addInstruction').onclick=()=>{const c=document.querySelectorAll('#instructionRows .instruction-row').length;document.getElementById('instructionRows').insertAdjacentHTML('beforeend',instructionRow('',c));bindEditor()};document.getElementById('saveRecipe').onclick=save;document.getElementById('archiveRecipe').onclick=archiveRecipe;const upload=document.getElementById('uploadImage');if(upload)upload.onclick=uploadImage;const apply=document.getElementById('applyAI');if(apply)apply.onclick=applyAI;const drop=document.getElementById('imageDrop'),input=document.getElementById('imageInput');if(drop&&input){drop.onclick=e=>{if(e.target!==input)input.click()};input.onchange=()=>{if(input.files?.[0]){const img=drop.querySelector('img')||document.createElement('img');img.src=URL.createObjectURL(input.files[0]);if(!img.parentNode)drop.prepend(img)}}}}
function collect(){const ingredients=[...document.querySelectorAll('#ingredientRows .ingredient-row')].map(row=>({quantity:row.querySelector('.qty').value.trim(),unit:row.querySelector('.unit').value.trim(),ingredient:row.querySelector('.ingredient').value.trim(),notes:row.querySelector('.notes').value.trim()})).filter(x=>x.ingredient);const instructions=[...document.querySelectorAll('#instructionRows .instruction')].map(e=>e.value.trim()).filter(Boolean);return {action:'update',id:activeId,name:document.getElementById('rName').value.trim(),category:document.getElementById('rCategory').value.trim(),description:document.getElementById('rDescription').value.trim(),yieldQuantity:document.getElementById('rYieldQty').value,yieldUnit:document.getElementById('rYieldUnit').value.trim(),ingredients,instructions,notes:document.getElementById('rNotes').value.trim(),mappingNotes:document.getElementById('rMapNotes').value.trim(),csrf_token:cfg.csrf}}
async function save(){const p=collect();if(!p.name)return alert('Recipe name is required.');await api('api/recipes.php',{method:'POST',body:JSON.stringify(p)});toast('Recipe saved');await openRecipe(activeId)}async function archiveRecipe(){if(!confirm('Archive this recipe?'))return;await api('api/recipes.php',{method:'POST',body:JSON.stringify({action:'archive',id:activeId,csrf_token:cfg.csrf})});activeId='';detail=null;document.getElementById('editor').classList.add('hidden');document.getElementById('emptyEditor').classList.remove('hidden');toast('Recipe archived');await loadList();window.GelatoRecipeAgentContext?.publish?.()}
async function uploadImage(){const input=document.getElementById('imageInput'),file=input?.files?.[0];if(!file)return alert('Choose a recipe image first.');const b=document.getElementById('uploadImage');b.disabled=true;b.textContent=cfg.canMap?'Analyzing + searching…':'Uploading…';const fd=new FormData();fd.append('csrf_token',cfg.csrf);fd.append('recipeId',activeId);fd.append('mapOnline',cfg.canMap?'1':'0');fd.append('image',file);try{const r=await fetch('api/recipe-image.php',{method:'POST',headers:{'X-CSRF-Token':cfg.csrf,'Accept':'application/json'},body:fd});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Upload failed.');toast(d.message);if(d.mappingError)alert('Image saved, but AI mapping could not finish: '+d.mappingError);await openRecipe(activeId)}catch(e){alert(e.message)}finally{b.disabled=false;b.textContent=cfg.canMap?'Upload + AI Map Online':'Upload Image'}}
async function applyAI(){const id=Number(document.getElementById('applyAI').dataset.image);await api('api/recipes.php',{method:'POST',body:JSON.stringify({action:'apply_ai',id:activeId,imageId:id,csrf_token:cfg.csrf})});toast('AI extraction applied');await openRecipe(activeId)}
if(cfg.canEdit)document.getElementById('newRecipe').onclick=async()=>{const name=prompt('Recipe name','Untitled Recipe');if(name===null)return;const d=await api('api/recipes.php',{method:'POST',body:JSON.stringify({action:'create',name:name||'Untitled Recipe',csrf_token:cfg.csrf})});await loadList();openRecipe(d.id)};document.querySelectorAll('[data-recipe-agent-prompt]').forEach(button=>button.addEventListener('click',()=>window.GelatoGlobalAgent?.send?.(button.dataset.recipeAgentPrompt||'')));document.getElementById('search').addEventListener('input',()=>{clearTimeout(window._rq);window._rq=setTimeout(loadList,180)});loadList().catch(e=>alert(e.message));})();
</script><script src="js/agent-page-context.js?v=20260916-1"></script><script src="js/recipe-agent-context.js?v=20260916-1"></script><script src="js/global-agent.js?v=20260916-1"></script><script src="js/dynamic-agent-canvas.js?v=20260916-1"></script><script src="js/universal-admin-page-shell.js?v=20260915-3"></script>
</body></html>
